import math

def triangle_area(a, b, c):
    def calculate_area(s, a, b, c):
        return math.sqrt(s * (s - a) * (s - b) * (s - c))

    if a <= 0 or b <= 0 or c <= 0:
        return -1

    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    s = (a + b + c) / 2
    area = calculate_area(s, a, b, c)

    return round(area, 2)

